//! Connector requirements discovery and live-module manifest emit.
//!
//! A connector may declare deploy/runtime requirements (required env,
//! permissions, opaque provider config) via an optional `requirements(name)`
//! hook.
//! Not every connector needs one: connectors with deploy-time environment,
//! permission, provider-configuration, or credential requirements implement
//! the hook. The CLI discovers `tools/mcp.{ts,py}`, and emits
//! deploy manifests by loading the live `_mda_connectors` aggregator and
//! calling `requirementsFromConnectors` / `requirements_from_connectors` —
//! not by matching first-party factory names.

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use anyhow::{bail, Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use super::discovery::entry_stem_name;
use crate::child;
use crate::error::child_failed;
use crate::langsmith::ConnectionOwnerPolicy;
use crate::project::{Language, Project};
use crate::toolchain;

/// Connector requirements keyed by their file-derived connector name. Each
/// value is the shape formerly known as a "channel manifest" — required env,
/// permissions, and opaque provider config.
pub(crate) type ConnectorRequirements = BTreeMap<String, Value>;

/// On-disk artifact written by [`emit_connector_requirements_for_entries`].
pub(crate) const CONNECTOR_REQUIREMENTS_FILE: &str = "connector-manifests.json";
/// On-disk artifact written by [`emit_channel_requirements_for_entries`].
pub(crate) const CHANNEL_REQUIREMENTS_FILE: &str = "channel-manifests.json";
/// On-disk artifact written by [`emit_mcp_connection_entries_for_entries`].
pub(crate) const MCP_CONNECTIONS_FILE: &str = "mcp-connections.json";
/// Channel requirements have the same manifest shape as connector requirements.
pub(crate) type ChannelRequirements = ConnectorRequirements;

const TYPESCRIPT_MCP_CONNECTIONS_SCRIPT: &str = r#"// Generated by `mda` — do not edit.
import { writeFileSync } from "node:fs";
import { connectors } from "./_mda_connectors.ts";

const entries = [];
for (const connector of connectors) {
  if (!connector || typeof connector !== "object" || connector.kind !== "mcp_servers") continue;
  const connectorName = typeof connector.name === "string" ? connector.name : "";
  const servers =
    "servers" in connector && connector.servers && typeof connector.servers === "object"
      ? connector.servers
      : null;
  if (!servers) continue;
  for (const [serverName, server] of Object.entries(servers)) {
    if (!server || typeof server !== "object") continue;
    const url = typeof server.url === "string" ? server.url : "";
    const connection =
      "connection" in server && server.connection && typeof server.connection === "object"
        ? server.connection
        : null;
    const slug = typeof connection?.slug === "string" ? connection.slug : "";
    const ownerPolicy =
      connection?.owner && typeof connection.owner === "object" && typeof connection.owner.type === "string"
        ? connection.owner.type
        : "";
    if (!url || !slug || !ownerPolicy) continue;
    entries.push({
      connector_name: connectorName,
      server_name: serverName,
      url,
      slug,
      owner_policy: ownerPolicy,
    });
  }
}

writeFileSync(
  new URL("./mcp-connections.json", import.meta.url),
  JSON.stringify(entries, null, 2) + "\n"
);
"#;

const PYTHON_MCP_CONNECTIONS_SCRIPT: &str = r#"# Generated by `mda` — do not edit.
from __future__ import annotations

import json
from pathlib import Path

from _mda_connectors import connectors

entries = []
for connector in connectors:
    if getattr(connector, "kind", None) != "mcp_servers":
        continue
    connector_name = getattr(connector, "name", "")
    config = getattr(connector, "config", None)
    servers = config.get("servers") if isinstance(config, dict) else None
    if not isinstance(servers, dict):
        continue
    for server_name, server in servers.items():
        if not isinstance(server, dict):
            continue
        url = server.get("url")
        connection = server.get("connection")
        slug = getattr(connection, "slug", None)
        owner = getattr(connection, "owner", None)
        owner_policy = owner.get("type") if isinstance(owner, dict) else None
        if not isinstance(url, str) or not isinstance(slug, str) or not isinstance(owner_policy, str):
            continue
        entries.append(
            {
                "connector_name": connector_name,
                "server_name": server_name,
                "url": url,
                "slug": slug,
                "owner_policy": owner_policy,
            }
        )

Path(__file__).resolve().parent.joinpath("mcp-connections.json").write_text(
    json.dumps(entries, indent=2) + "\n",
    encoding="utf-8",
)
"#;

/// One connection declaration extracted from a live `defineMcp(...)` / `define_mcp(...)` module.
#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
pub(crate) struct McpConnectionEntry {
    pub connector_name: String,
    pub server_name: String,
    pub url: String,
    pub slug: String,
    pub owner_policy: String,
}

/// Collect unique `requiredEnv` entries from compiled connector requirements.
pub(crate) fn required_env_from_connector_requirements(
    requirements: &ConnectorRequirements,
) -> Vec<String> {
    let mut keys = HashSet::new();
    for manifest in requirements.values() {
        if let Some(arr) = manifest.get("requiredEnv").and_then(Value::as_array) {
            for entry in arr {
                if let Some(key) = entry.as_str() {
                    keys.insert(key.to_string());
                }
            }
        }
    }
    let mut out: Vec<String> = keys.into_iter().collect();
    out.sort();
    out
}

/// Connection names under `mda/` belong to MDA: a channel's setup provides
/// them, such as `mda/github-token`, the GitHub App's installation token. They
/// are not workspace connections, so deploy neither checks for them nor
/// creates them, and a new channel needs no change here.
const RESERVED_CONNECTION_PREFIX: &str = "mda/";

fn is_channel_reserved_agent_connection(slug: &str) -> bool {
    slug.starts_with(RESERVED_CONNECTION_PREFIX)
}

/// The `mda/` agent connections the project's channels say their setup
/// provides, such as `mda/github-token`, each with the name of the channel
/// that provides it.
pub(crate) fn channel_provided_connections(
    channels: &ChannelRequirements,
) -> BTreeMap<String, String> {
    let mut provided = BTreeMap::new();
    for (channel, manifest) in channels {
        for slug in declared_slugs(manifest, "agentConnections") {
            if is_channel_reserved_agent_connection(slug) {
                provided.insert(slug.to_string(), channel.clone());
            }
        }
    }
    provided
}

/// The `mda/` agent connections the project's connectors read that none of
/// its channels provides, so reading them fails at runtime.
pub(crate) fn unprovided_reserved_connections(
    connectors: &ConnectorRequirements,
    channels: &ChannelRequirements,
) -> Vec<String> {
    let provided = channel_provided_connections(channels);
    let slugs: BTreeSet<&str> = connectors
        .values()
        .flat_map(|manifest| declared_slugs(manifest, "agentConnections"))
        .filter(|slug| is_channel_reserved_agent_connection(slug) && !provided.contains_key(*slug))
        .collect();
    slugs.into_iter().map(str::to_string).collect()
}

fn declared_slugs<'a>(manifest: &'a Value, field: &str) -> impl Iterator<Item = &'a str> {
    manifest
        .get(field)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
}

/// Why a project cannot declare `slug` as a user connection: names under
/// `mda/` are agent connections a channel's setup provides, and reading an
/// app's token as the person running the agent is not supported yet.
/// `provided` is what [`channel_provided_connections`] returns.
pub(crate) fn reserved_user_connection_error(
    slug: &str,
    provided: &BTreeMap<String, String>,
) -> Option<String> {
    if !is_channel_reserved_agent_connection(slug) {
        return None;
    }
    Some(match provided.get(slug) {
        Some(channel) => format!(
            "'{slug}' is not supported as a user connection yet: the {channel} channel's app \
             provides it as an agent connection. Use connections.get(\"{slug}\", {{ type: \
             \"agent\" }}) to act as the app."
        ),
        None => format!(
            "'{slug}' cannot be a user connection: names under mda/ are reserved for the \
             agent connections channels provide. Use connections.get(\"{slug}\", {{ type: \
             \"agent\" }}) for a channel's token, or rename the connection."
        ),
    })
}

/// Collect unique user-owned connection slugs from compiled connector requirements.
pub(crate) fn user_connections_from_connector_requirements(
    requirements: &ConnectorRequirements,
) -> Vec<String> {
    let mut slugs = HashSet::new();
    for manifest in requirements.values() {
        if let Some(entries) = manifest.get("userConnections").and_then(Value::as_array) {
            for entry in entries {
                if let Some(slug) = entry.as_str() {
                    slugs.insert(slug.to_string());
                }
            }
        }
    }
    let mut out: Vec<String> = slugs.into_iter().collect();
    out.sort();
    out
}

/// Collect unique agent-owned connection slugs from compiled connector requirements.
pub(crate) fn agent_connections_from_connector_requirements(
    requirements: &ConnectorRequirements,
) -> Vec<String> {
    let mut slugs = HashSet::new();
    for manifest in requirements.values() {
        if let Some(entries) = manifest.get("agentConnections").and_then(Value::as_array) {
            for entry in entries {
                if let Some(slug) = entry.as_str() {
                    if !is_channel_reserved_agent_connection(slug) {
                        slugs.insert(slug.to_string());
                    }
                }
            }
        }
    }
    let mut out: Vec<String> = slugs.into_iter().collect();
    out.sort();
    out
}

/// Unique connection slugs referenced by compiled connector requirements.
pub(crate) fn referenced_connection_slugs(requirements: &ConnectorRequirements) -> Vec<String> {
    let mut slugs = BTreeSet::new();
    slugs.extend(user_connections_from_connector_requirements(requirements));
    slugs.extend(agent_connections_from_connector_requirements(requirements));
    slugs.into_iter().collect()
}

/// Resolve owner policy for one slug from compiled connector requirements.
///
/// Returns `None` when the slug is absent from the manifest or listed under both
/// agent and user ownership.
pub(crate) fn connection_owner_policy_for_slug(
    requirements: &ConnectorRequirements,
    slug: &str,
) -> Option<ConnectionOwnerPolicy> {
    let is_agent = agent_connections_from_connector_requirements(requirements)
        .iter()
        .any(|entry| entry == slug);
    let is_user = user_connections_from_connector_requirements(requirements)
        .iter()
        .any(|entry| entry == slug);
    match (is_agent, is_user) {
        (true, false) => Some(ConnectionOwnerPolicy::Agent),
        (false, true) => Some(ConnectionOwnerPolicy::User),
        _ => None,
    }
}

/// Load requirements previously written by [`emit_connector_requirements_for_entries`].
pub(crate) fn load_connector_requirements(out_dir: &Path) -> Result<ConnectorRequirements> {
    load_requirements(out_dir, CONNECTOR_REQUIREMENTS_FILE)
}

/// Load MCP connection entries previously written by [`emit_mcp_connection_entries_for_entries`].
pub(crate) fn load_mcp_connection_entries(out_dir: &Path) -> Result<Vec<McpConnectionEntry>> {
    let path = out_dir.join(MCP_CONNECTIONS_FILE);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let text =
        fs::read_to_string(&path).with_context(|| format!("failed to read {}", path.display()))?;
    serde_json::from_str(&text).with_context(|| format!("failed to parse {}", path.display()))
}

/// Load requirements previously written by [`emit_channel_requirements_for_entries`].
pub(crate) fn load_channel_requirements(out_dir: &Path) -> Result<ChannelRequirements> {
    load_requirements(out_dir, CHANNEL_REQUIREMENTS_FILE)
}

fn load_requirements(out_dir: &Path, file_name: &str) -> Result<ConnectorRequirements> {
    let path = out_dir.join(file_name);
    if !path.exists() {
        return Ok(BTreeMap::new());
    }
    let text =
        fs::read_to_string(&path).with_context(|| format!("failed to read {}", path.display()))?;
    let value: Value = serde_json::from_str(&text)
        .with_context(|| format!("failed to parse {}", path.display()))?;
    let Value::Object(object) = value else {
        bail!("{file_name} must be a JSON object");
    };
    Ok(object.into_iter().collect())
}

/// Emit channel requirements from the live `_mda_channels` aggregator.
pub(crate) fn emit_channel_requirements_for_entries(
    project: &Project,
    out_dir: &Path,
    entries: &[PathBuf],
) -> Result<ChannelRequirements> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();
    for rel in entries {
        let name = entry_stem_name(rel, "channel")?;
        if !seen.insert(name.clone()) {
            bail!("duplicate channel name '{name}' from channels/");
        }
        names.push(name);
    }
    names.sort();
    if names.is_empty() {
        let _ = fs::remove_file(out_dir.join(CHANNEL_REQUIREMENTS_FILE));
        return Ok(BTreeMap::new());
    }
    match project.language {
        Language::TypeScript => emit_typescript_channel_requirements(out_dir)?,
        Language::Python => emit_python_channel_requirements(project, out_dir)?,
    }
    load_channel_requirements(out_dir)
}

/// Import `_mda_connectors`, call `requirementsFromConnectors` /
/// `requirements_from_connectors`, and write [`CONNECTOR_REQUIREMENTS_FILE`].
///
/// Requires a successful compile that vendored `managed-deepagents` and copied
/// the project's connector modules into `out_dir`. Reuses connector paths
/// already discovered during compile (avoids a second AST walk). Unlike the former channel manifests (where every channel
/// always had one), not every discovered connector declares requirements, so
/// this never bails on a discovered name missing from the result.
pub(crate) fn emit_connector_requirements_for_entries(
    project: &Project,
    out_dir: &Path,
    entries: &[PathBuf],
) -> Result<ConnectorRequirements> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();
    for rel in entries {
        let name = entry_stem_name(rel, "connector")?;
        if !seen.insert(name.clone()) {
            bail!("duplicate connector name '{name}'");
        }
        names.push(name);
    }
    names.sort();
    emit_connector_requirements_named(project, out_dir, &names)
}

/// Import `_mda_connectors`, read each `defineMcp(...)` declaration's
/// named servers, and write [`MCP_CONNECTIONS_FILE`].
pub(crate) fn emit_mcp_connection_entries_for_entries(
    project: &Project,
    out_dir: &Path,
    entries: &[PathBuf],
) -> Result<Vec<McpConnectionEntry>> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();
    for rel in entries {
        let name = entry_stem_name(rel, "connector")?;
        if !seen.insert(name.clone()) {
            bail!("duplicate connector name '{name}'");
        }
        names.push(name);
    }
    names.sort();
    emit_mcp_connection_entries_named(project, out_dir, &names)
}

fn emit_connector_requirements_named(
    project: &Project,
    out_dir: &Path,
    names: &[String],
) -> Result<ConnectorRequirements> {
    if names.is_empty() {
        let _ = fs::remove_file(out_dir.join(CONNECTOR_REQUIREMENTS_FILE));
        return Ok(BTreeMap::new());
    }

    match project.language {
        Language::TypeScript => emit_typescript_connector_requirements(out_dir)?,
        Language::Python => emit_python_connector_requirements(project, out_dir)?,
    }

    load_connector_requirements(out_dir)
}

fn emit_mcp_connection_entries_named(
    project: &Project,
    out_dir: &Path,
    names: &[String],
) -> Result<Vec<McpConnectionEntry>> {
    if names.is_empty() {
        let _ = fs::remove_file(out_dir.join(MCP_CONNECTIONS_FILE));
        return Ok(Vec::new());
    }

    match project.language {
        Language::TypeScript => emit_typescript_mcp_connection_entries(out_dir)?,
        Language::Python => emit_python_mcp_connection_entries(project, out_dir)?,
    }

    load_mcp_connection_entries(out_dir)
}

fn emit_typescript_connector_requirements(out_dir: &Path) -> Result<()> {
    // Compile only materializes a lockfile (`npm install --package-lock-only`).
    // Connector modules import `managed-deepagents`, whose connector factories
    // pull runtime deps (`@langchain/langgraph-sdk`, …). Install the build's
    // production deps so emit can resolve them locally — same tree the remote
    // builder gets after `npm ci`.
    install_typescript_build_deps(out_dir)?;
    // TS builds expose the runtime as an npm workspace. If install did not
    // link it (partial tree), symlink so emit can `import "managed-deepagents/…"`.
    ensure_vendored_runtime_node_link(out_dir)?;

    let script_name = "_mda_emit_connector_requirements.mts";
    let script_path = out_dir.join(script_name);
    let script = r#"// Generated by `mda` — do not edit.
import { writeFileSync } from "node:fs";
import { connectors } from "./_mda_connectors.ts";
import { requirementsFromConnectors } from "managed-deepagents/runtime";

const requirements = requirementsFromConnectors(connectors);
writeFileSync(
  new URL("./connector-manifests.json", import.meta.url),
  JSON.stringify(requirements, null, 2) + "\n"
);
"#;
    fs::write(&script_path, script)
        .with_context(|| format!("failed to write {}", script_path.display()))?;

    let output = run_tsx(out_dir, script_name)?;
    if !output.status.success() {
        return Err(child_failed(
            &output,
            format!(
                "failed to emit connector requirements via Node/tsx (exit {}). \
                 Ensure `tools/mcp` exports a valid `mcp` declaration and that \
                 project dependencies are installed.",
                output.status.code().unwrap_or(-1)
            ),
        ));
    }
    Ok(())
}

fn emit_typescript_mcp_connection_entries(out_dir: &Path) -> Result<()> {
    install_typescript_build_deps(out_dir)?;
    ensure_vendored_runtime_node_link(out_dir)?;

    let script_name = "_mda_emit_mcp_connections.mts";
    let script_path = out_dir.join(script_name);
    fs::write(&script_path, TYPESCRIPT_MCP_CONNECTIONS_SCRIPT)
        .with_context(|| format!("failed to write {}", script_path.display()))?;

    let output = run_tsx(out_dir, script_name)?;
    if !output.status.success() {
        return Err(child_failed(
            &output,
            format!(
                "failed to emit MCP connection entries via Node/tsx (exit {}). \
                 Ensure `tools/mcp` exports a valid `mcp` declaration and that \
                 project dependencies are installed.",
                output.status.code().unwrap_or(-1)
            ),
        ));
    }
    Ok(())
}

fn emit_typescript_channel_requirements(out_dir: &Path) -> Result<()> {
    install_typescript_build_deps(out_dir)?;
    ensure_vendored_runtime_node_link(out_dir)?;
    let script_name = "_mda_emit_channel_requirements.mts";
    let script_path = out_dir.join(script_name);
    let script = r#"// Generated by `mda` — do not edit.
import { writeFileSync } from "node:fs";
import { channels } from "./_mda_channels.ts";
import { requirementsFromChannels } from "managed-deepagents/runtime";

const requirements = requirementsFromChannels(channels);
writeFileSync(
  new URL("./channel-manifests.json", import.meta.url),
  JSON.stringify(requirements, null, 2) + "\n"
);
"#;
    fs::write(&script_path, script)
        .with_context(|| format!("failed to write {}", script_path.display()))?;
    let output = run_tsx(out_dir, script_name)?;
    if !output.status.success() {
        return Err(child_failed(
            &output,
            format!(
                "failed to emit channel requirements via Node/tsx (exit {}). \
                 Ensure `channels/*` exports branded Channel objects and that \
                 project dependencies are installed.",
                output.status.code().unwrap_or(-1)
            ),
        ));
    }
    Ok(())
}

/// Install production deps from the compile-generated lockfile into `out_dir`.
fn install_typescript_build_deps(out_dir: &Path) -> Result<()> {
    if !out_dir.join("package.json").is_file() {
        bail!(
            "missing package.json in {} (compile must rewrite dependencies before connector requirements emit)",
            out_dir.display()
        );
    }
    if !out_dir.join("package-lock.json").is_file() {
        bail!(
            "missing package-lock.json in {} (compile must materialize a lockfile before connector requirements emit)",
            out_dir.display()
        );
    }
    // Connector, MCP, and channel emit each need this tree, and a deploy runs
    // all three back to back. Install once per lockfile, not once per emit.
    let stamp = out_dir.join("node_modules").join(TYPESCRIPT_EMIT_STAMP);
    if typescript_emit_deps_ready(out_dir, &stamp)? {
        return Ok(());
    }
    // Match the lockfile-verification install used in compile tests: ignore
    // lifecycle scripts (CLI optional binaries are irrelevant for emit).
    // `--no-save` adds tsx for the emit scripts without touching the manifests
    // the remote builder installs from.
    const NPM_INSTALL_ARGS: &[&str] = &[
        "install",
        "--omit=dev",
        "--ignore-scripts",
        "--no-save",
        EMIT_TSX_SPEC,
    ];
    let command = format!(
        "{} {}",
        toolchain::npm_program(),
        NPM_INSTALL_ARGS.join(" ")
    );
    let output = child::output(toolchain::npm().args(NPM_INSTALL_ARGS).current_dir(out_dir))
        .with_context(|| format!("failed to run {command} for connector requirements emit"))?;
    if !output.status.success() {
        return Err(child_failed(
            &output,
            format!("{command} failed (needed to resolve connector imports)"),
        ));
    }
    // Fingerprint after the install: npm may normalize the lockfile it read.
    write_stamp(&stamp, &typescript_emit_fingerprint(out_dir)?)
}

/// Marker inside `node_modules` naming the manifests the emit install came
/// from. Living in the tree it describes, it disappears with it (`npm ci`,
/// a manual delete) instead of vouching for an install that is gone.
const TYPESCRIPT_EMIT_STAMP: &str = ".mda-emit-deps-stamp";

/// tsx installed next to the emit deps so [`run_tsx`] runs it with `node`
/// directly. Without it, emit falls back to `npx --yes tsx`, whose package
/// resolution costs about a second on every emit. Pinned so the emit tree is
/// reproducible; part of the stamp fingerprint, so a bump reinstalls.
const EMIT_TSX_SPEC: &str = "tsx@4.23.15";

/// The stamp alone is not enough: `mda dev` emits into `.mda/dev`, and its plain
/// `npm install` prunes the `--no-save` tsx while leaving the stamp in place.
fn typescript_emit_deps_ready(out_dir: &Path, stamp: &Path) -> Result<bool> {
    Ok(local_tsx_cli(out_dir).is_file()
        && stamp_matches(stamp, &typescript_emit_fingerprint(out_dir)?))
}

fn local_tsx_cli(out_dir: &Path) -> PathBuf {
    out_dir
        .join("node_modules")
        .join("tsx")
        .join("dist")
        .join("cli.mjs")
}

/// Marker inside [`PYTHON_EMIT_SITE_DIR`] naming the interpreter and runtime
/// manifest its packages were installed for.
const PYTHON_EMIT_STAMP: &str = ".mda-emit-stamp";

fn typescript_emit_fingerprint(out_dir: &Path) -> Result<String> {
    Ok(fingerprint(&[
        EMIT_TSX_SPEC.as_bytes(),
        &read_if_present(&out_dir.join("package.json"))?,
        &read_if_present(&out_dir.join("package-lock.json"))?,
    ]))
}

/// Keyed on the interpreter as well as the manifest: a site installed for one
/// Python is not importable from another (compiled wheels, ABI tags).
///
/// The emit interpreter is a venv's `bin/python`, whose path survives a venv
/// rebuilt on another Python (`uv sync` after a `.python-version` bump). So
/// the identity also covers what that path resolves to (usually a versioned
/// `python3.X`) and the venv's `pyvenv.cfg`, which records the version even
/// where the venv copies the binary instead of linking it.
fn python_emit_fingerprint(out_dir: &Path, python: &Path) -> Result<String> {
    // An interpreter that cannot be resolved here fails at install time; the
    // raw path is enough to key the (never-matching) stamp until then.
    let resolved = fs::canonicalize(python).unwrap_or_else(|_| python.to_path_buf());
    let pyvenv_cfg = match python.parent().and_then(Path::parent) {
        Some(venv) => read_if_present(&venv.join("pyvenv.cfg"))?,
        None => Vec::new(),
    };
    Ok(fingerprint(&[
        crate::version::package_version().as_bytes(),
        python.as_os_str().as_encoded_bytes(),
        resolved.as_os_str().as_encoded_bytes(),
        &pyvenv_cfg,
        &read_if_present(&out_dir.join("__runtime__").join("pyproject.toml"))?,
    ]))
}

fn fingerprint(parts: &[&[u8]]) -> String {
    use std::hash::{DefaultHasher, Hash, Hasher};

    let mut hasher = DefaultHasher::new();
    for part in parts {
        part.hash(&mut hasher);
    }
    format!("{:x}", hasher.finish())
}

fn read_if_present(path: &Path) -> Result<Vec<u8>> {
    match fs::read(path) {
        Ok(bytes) => Ok(bytes),
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(Vec::new()),
        Err(err) => Err(err).with_context(|| format!("failed to read {}", path.display())),
    }
}

/// A stamp that is missing or unreadable never matches, so the caller
/// reinstalls rather than trusting an install it cannot vouch for.
fn stamp_matches(stamp: &Path, fingerprint: &str) -> bool {
    fs::read_to_string(stamp).is_ok_and(|recorded| recorded.trim() == fingerprint)
}

fn write_stamp(stamp: &Path, fingerprint: &str) -> Result<()> {
    fs::write(stamp, format!("{fingerprint}\n"))
        .with_context(|| format!("failed to write {}", stamp.display()))
}

/// Symlink `node_modules/managed-deepagents` → `../__runtime__` for local emit.
fn ensure_vendored_runtime_node_link(out_dir: &Path) -> Result<()> {
    let runtime = out_dir.join("__runtime__");
    if !runtime.is_dir() {
        bail!(
            "missing vendored runtime at {} (compile must vendor managed-deepagents before connector requirements emit)",
            runtime.display()
        );
    }
    let node_modules = out_dir.join("node_modules");
    fs::create_dir_all(&node_modules)
        .with_context(|| format!("failed to create {}", node_modules.display()))?;
    let link = node_modules.join("managed-deepagents");
    if link.exists() || link.symlink_metadata().is_ok() {
        // Already present (prior emit, or a real install). Prefer leaving a real
        // directory install alone; replace a symlink so it always points at
        // this build's `__runtime__`.
        let meta = fs::symlink_metadata(&link)
            .with_context(|| format!("failed to stat {}", link.display()))?;
        if meta.file_type().is_symlink() {
            fs::remove_file(&link)
                .with_context(|| format!("failed to remove stale link {}", link.display()))?;
        } else if meta.is_dir() {
            return Ok(());
        } else {
            fs::remove_file(&link)
                .with_context(|| format!("failed to remove {}", link.display()))?;
        }
    }
    symlink_relative_runtime(&link)?;
    Ok(())
}

fn symlink_relative_runtime(link: &Path) -> Result<()> {
    // Relative to `node_modules/managed-deepagents`.
    let target = Path::new("../__runtime__");
    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(target, link).with_context(|| {
            format!(
                "failed to symlink {} -> {}",
                link.display(),
                target.display()
            )
        })
    }
    #[cfg(windows)]
    {
        std::os::windows::fs::symlink_dir(target, link).with_context(|| {
            format!(
                "failed to symlink {} -> {}",
                link.display(),
                target.display()
            )
        })
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = (link, target);
        bail!("connector requirements emit requires unix or windows to link the vendored runtime")
    }
}

fn run_tsx(out_dir: &Path, script_name: &str) -> Result<Output> {
    // Run tsx via `node` with a path relative to `out_dir`. npm `.bin/tsx` is
    // often a symlink to `cli.mjs`; execing that shim while `current_dir` is
    // `out_dir` breaks when the shim path is absolute or repo-relative
    // (`examples/.../.mda/build/node_modules/.bin/tsx` → ENOENT).
    let tsx_cli = local_tsx_cli(out_dir);
    if tsx_cli.is_file() {
        let tsx_cli = fs::canonicalize(&tsx_cli)
            .with_context(|| format!("failed to resolve {}", tsx_cli.display()))?;
        return child::output(
            toolchain::node()
                .arg(&tsx_cli)
                .arg(script_name)
                .current_dir(out_dir),
        )
        .with_context(|| {
            format!(
                "failed to run {} via {}",
                tsx_cli.display(),
                toolchain::node_program()
            )
        });
    }
    let bin_dir = out_dir.join("node_modules").join(".bin");
    if let Some(local_tsx) = toolchain::npm_bin(&bin_dir, "tsx") {
        // Windows `.cmd` shims are not Node scripts; run them relative to `out_dir`.
        let shim_name = local_tsx
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| "tsx".to_string());
        let tsx_shim = Path::new("node_modules").join(".bin").join(shim_name);
        return child::output(
            Command::new(&tsx_shim)
                .arg(script_name)
                .current_dir(out_dir),
        )
        .with_context(|| format!("failed to run {}", tsx_shim.display()));
    }
    let output = child::output(
        toolchain::npx()
            .args(["--yes", "tsx", script_name])
            .current_dir(out_dir),
    )
    .with_context(|| {
        format!(
            "failed to run {} tsx for connector requirements emit",
            toolchain::npx_program()
        )
    })?;
    Ok(output)
}

fn emit_python_connector_requirements(project: &Project, out_dir: &Path) -> Result<()> {
    // Compile vendors source under `__runtime__/` but does not install its
    // declared deps (pydantic). Connector factories import through the package
    // barrel and need those at emit time — same role as
    // `install_typescript_build_deps` for the TS path.
    let python = toolchain::python_for_emit(&project.root, out_dir)?;
    install_python_emit_deps(out_dir, &python)?;

    let script_name = "_mda_emit_connector_requirements.py";
    let script_path = out_dir.join(script_name);
    let script = r#"# Generated by `mda` — do not edit.
from __future__ import annotations

import json
from pathlib import Path

from _mda_connectors import connectors
from managed_deepagents._connector import requirements_from_connectors

requirements = requirements_from_connectors(connectors)
Path(__file__).resolve().parent.joinpath("connector-manifests.json").write_text(
    json.dumps(requirements, indent=2) + "\n",
    encoding="utf-8",
)
"#;
    fs::write(&script_path, script)
        .with_context(|| format!("failed to write {}", script_path.display()))?;

    let output = child::output(
        Command::new(&python)
            .arg(script_name)
            .current_dir(out_dir)
            .env(
                "PYTHONPATH",
                pythonpath_with(out_dir, std::env::var_os("PYTHONPATH")),
            ),
    )
    .with_context(|| {
        format!(
            "failed to run {} for connector requirements emit",
            python.display()
        )
    })?;
    if !output.status.success() {
        return Err(child_failed(
            &output,
            format!(
                "failed to emit connector requirements via {} (exit {}). \
                 Install project deps (`uv sync`) and ensure `tools/mcp.py` exports a valid \
                 `mcp` declaration.",
                python.display(),
                output.status.code().unwrap_or(-1)
            ),
        ));
    }
    Ok(())
}

