        assert!(!typescript_emit_deps_ready(&out_dir, &stamp).unwrap());

        let tsx_cli = local_tsx_cli(&out_dir);
        fs::create_dir_all(tsx_cli.parent().unwrap()).unwrap();
        fs::write(&tsx_cli, "").unwrap();
        assert!(typescript_emit_deps_ready(&out_dir, &stamp).unwrap());
